      "content": "{\n  \"name\": \"@mars-sea/dsh-commandcode-provider\",\n  \"version\": \"0.15.5\",\n  \"description\": \"Unofficial DeepSeek Harness LLM provider plugin for Command Code, ported from pi-commandcode-provider (MIT). Registers the 'commandcode' provider route with a Models-page card and live model catalog.\",\n  \"icon\": \"./icon.svg\",\n  \"type\": \"module\",\n  \"main\": \"./lib/index.js\",\n  \"types\": \"./lib/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"default\": \"./lib/client.js\"\n    },\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"compatibility\": {\n      \"dshReleases\": {\n        \"0.2.1-rc.2\": \"compatible\",\n        \"0.2.1-rc.3\": \"compatible\",\n        \"0.2.1-rc.4\": \"compatible\"\n      },\n      \"dsh\": \">=0.2.1-rc.2 <0.2.2-0\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-api-remotes\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"files\": [\n    \"lib\",\n    \"!lib/**/*.map\",\n    \"assets\",\n    \"icon.svg\",\n    \"locale\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.zh-CN.md\",\n    \"CHANGELOG.md\",\n    \"LICENSE\",\n    \"NOTICE\"\n  ],\n  \"scripts\": {\n    \"build\": \"tsdown\",\n    \"prepare\": \"tsdown\",\n    \"test:install\": \"node scripts/verify-isolated-install.mjs\",\n    \"test:engine\": \"node scripts/verify-engine-load.mjs\",\n    \"test:pack\": \"node scripts/verify-package-exports.mjs\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"test\": \"node --import tsx --test tests/**/*.test.ts\"\n  },\n  \"engines\": {\n    \"node\": \">=22\",\n    \"dsh\": \">=0.2.1-rc.2 <0.2.2-0\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Mars-Sea/dsh-commandcode-provider.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/Mars-Sea/dsh-commandcode-provider/issues\"\n  },\n  \"homepage\": \"https://github.com/Mars-Sea/dsh-commandcode-provider#readme\",\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"commandcode\",\n    \"command-code\",\n    \"llm\",\n    \"adapter\",\n    \"provider\",\n    \"plugin\",\n    \"bundle\"\n  ],\n  \"license\": \"MIT\",\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"~4.0.5\",\n    \"@deepseek-ai/dsh-api-remotes\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-attachment\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-client-locale\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-commands\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-credentials\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-launch-environment\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-llm\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-settings\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-timeout\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-typert-protocol\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/schemastery\": \"~3.18.5\",\n    \"react\": \"^18.2.0\",\n    \"@deepseek-ai/dsh-web\": \">=0.2.1-rc.2 <0.2.2-0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-client-ui-primitives\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-slots\": {\n      \"optional\": true\n    },\n    \"react\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"~4.0.5\",\n    \"@deepseek-ai/dsh-agent\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-api-remotes\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-attachment\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-client-locale\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-commands\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-credentials\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-launch-environment\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-llm\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-settings\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-session\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-scope\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-session-projection\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-timeout\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-typert-protocol\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/dsh-web\": \">=0.2.1-rc.2 <0.2.2-0\",\n    \"@deepseek-ai/schemastery\": \"~3.18.5\",\n    \"@types/node\": \"^22.0.0\",\n    \"@types/react\": \"^18.3.1\",\n    \"@types/react-test-renderer\": \"^19.3.0\",\n    \"parse5\": \"8.0.1\",\n    \"react\": \"^18.2.0\",\n    \"react-test-renderer\": \"^18.3.1\",\n    \"tsdown\": \"^0.22.2\",\n    \"tsx\": \"^4.23.12\",\n    \"typescript\": \"^6.0.3\"\n  },\n  \"overrides\": {\n    \"zod\": \"^4.6.6\"\n  }\n}\n"
